function acknowledgementStatusLabel(
  acknowledgement: PurchaseOrderAcknowledgement
) {
  return acknowledgement.comparison_status || "Pending";
}


type AcknowledgementAiMeta = {
  extracted_at: string | null;
  model: string | null;
  overall_confidence: number | null;
  notes: string | null;
};

function acknowledgementAiMeta(
  acknowledgement: PurchaseOrderAcknowledgement
): AcknowledgementAiMeta | null {
  const details =
    acknowledgement.comparison_details &&
    typeof acknowledgement.comparison_details === "object" &&
    !Array.isArray(
      acknowledgement.comparison_details
    )
      ? (acknowledgement.comparison_details as Record<
          string,
          unknown
        >)
      : null;

  if (!details) return null;

  const raw =
    details.ai_extraction;

  if (
    !raw ||
    typeof raw !== "object" ||
    Array.isArray(raw)
  ) {
    return null;
  }

  const meta =
    raw as Record<
      string,
      unknown
    >;

  const confidence =
    Number(
      meta.overall_confidence
    );

  return {
    extracted_at:
      meta.extracted_at
        ? String(
            meta.extracted_at
          )
        : null,
    model:
      meta.model
        ? String(meta.model)
        : null,
    overall_confidence:
      Number.isFinite(
        confidence
      )
        ? confidence
        : null,
    notes:
      meta.notes
        ? String(meta.notes)
        : null,
  };
}


