function reportTypeLabel(type: ReportType) {
  return (
    reportDefinitions.find(
      (definition) => definition.type === type
    )?.title || "Report"
  );
}

function reportDefinitionText(type: ReportType) {
  switch (type) {
    case "open_quotes_by_salesperson":
      return "Every quote whose status is not Archived. Converted quotes are normally archived during conversion, so they drop out automatically.";
    case "unacknowledged_pos":
      return "Every non-draft PO with no acknowledgement number, acknowledgement date, or uploaded acknowledgement record.";
    case "uninvoiced_pos":
      return "Every non-draft PO without a linked vendor invoice, ignoring invoices marked Void.";
    case "sales_without_pos":
      return "Any sales order with at least one Special Order line that is not linked to a purchase-order line. Inventory-only sales are excluded, and partially generated POs are still caught.";
    case "sales_by_salesperson":
      return "Sales order performance grouped by salesperson. Gross profit is merchandise revenue minus the best available item cost, using acknowledged cost when available and expected cost otherwise.";
    case "sales_by_manufacturer":
      return "Merchandise lines grouped by manufacturer. Freight, tax and order-level adjustments are excluded so manufacturer margin reflects merchandise performance.";
    case "gross_margin":
      return "Sale-level merchandise revenue, best available item cost, gross profit and gross-margin percentage.";
    case "commission_due":
      return "Sales that are paid in full using posted payment history. Commission is calculated only on line items marked commissionable, using the salesperson's default commission rate.";
    case "outstanding_balances":
      return "Sales orders where posted payments do not yet cover merchandise, freight, adjustments and tax.";
    case "inventory_valuation":
      return "Active inventory with non-zero quantity on hand, valued using the item's unit cost and MSRP.";
    case "po_status_aging":
      return "Purchase orders that are not Closed, showing days since the PO order date and current workflow status.";
    case "acknowledgement_issues":
      return "Unresolved acknowledgement comparison flags, including vendor, PO, SKU, quantity, cost and freight discrepancies.";
    case "vendor_invoice_aging":
      return "Vendor invoices in Open or Approved status. Partial vendor payments are deducted so the report shows the true remaining balance. Paid and Void invoices are excluded.";
    case "expenses":
      return "Recorded operating expenses, with optional date filtering and links back to related manufacturer, PO or sale when present.";
    case "daily_cash_summary":
      return "Daily Cash batches with system total, reconciled actual total, variance and payment count.";
  }
}

function reportUsesDateRange(type: ReportType) {
  return [
    "sales_by_salesperson",
    "sales_by_manufacturer",
    "gross_margin",
    "commission_due",
    "outstanding_balances",
    "expenses",
    "daily_cash_summary",
  ].includes(type);
}

function reportUsesSalespersonFilter(type: ReportType) {
  return [
    "open_quotes_by_salesperson",
    "sales_by_salesperson",
    "gross_margin",
    "commission_due",
    "outstanding_balances",
  ].includes(type);
}

function daysSinceReportDate(dateString: string | null | undefined) {
  if (!dateString) return 0;

  const start = new Date(`${dateString}T00:00:00`);
  const now = new Date();
  const today = new Date(
    now.getFullYear(),
    now.getMonth(),
    now.getDate()
  );

  return Math.max(
    0,
    Math.floor(
      (today.getTime() - start.getTime()) /
        (1000 * 60 * 60 * 24)
    )
  );
}

