  useEffect(() => {
    if (!supabase) {
      setMessage("Supabase connection settings are missing.");
      setLoading(false);
      return;
    }

    let active = true;
    const connectionTimeout = window.setTimeout(() => {
      if (!active) return;
      setMessage(
        "The connection took too long. Please sign in again."
      );
      setLoading(false);
    }, 8000);

    supabase.auth
      .getSession()
      .then(({ data, error }) => {
        if (!active) return;

        if (error) {
          setMessage(`Connection error: ${error.message}`);
          setSession(null);
          return;
        }

        setSession(data.session);
      })
      .catch((error: unknown) => {
        if (!active) return;
        setMessage(
          error instanceof Error
            ? `Connection error: ${error.message}`
            : "Could not connect to the Hub. Please sign in again."
        );
        setSession(null);
      })
      .finally(() => {
        if (!active) return;
        window.clearTimeout(connectionTimeout);
        setLoading(false);
      });

    const { data: listener } = supabase.auth.onAuthStateChange(
      (_event, nextSession) => {
        setSession(nextSession);
      }
    );

    return () => {
      active = false;
      window.clearTimeout(connectionTimeout);
      listener.subscription.unsubscribe();
    };
  }, [supabase]);

  const loadProfile = useCallback(async () => {
    if (!supabase || !session?.user?.id) {
      setProfile(null);
      return;
    }

    const { data, error } = await supabase
      .from("profiles")
      .select(
        "id,display_name,email,phone,role,default_commission_rate,active"
      )
      .eq("id", session.user.id)
      .single();

    if (error) {
      setMessage(`Profile error: ${error.message}`);
      return;
    }

    setProfile(data as Profile);
  }, [supabase, session?.user?.id]);

