  async function teamAdminApi(
    body: Record<string, unknown>
  ) {
    if (!session?.access_token) {
      throw new Error(
        "Your Hub session is not available."
      );
    }

    const response = await fetch(
      "/api/team",
      {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${session.access_token}`,
        },
        body: JSON.stringify(body),
      }
    );

    const payload = await response
      .json()
      .catch(() => ({}));

    return {
      ok: response.ok,
      status: response.status,
      payload,
    };
  }

  async function loadAdminTeam(
    quiet = false
  ) {
    setAdminTeamLoading(true);

    try {
      const result = await teamAdminApi({
        action: "list",
      });

      if (!result.ok) {
        const errorMessage =
          result.payload?.error ||
          "Team management could not be loaded.";

        if (!quiet) {
          setMessage(errorMessage);
        }
        return;
      }

      setAdminTeam(
        (result.payload?.team ||
          []) as Profile[]
      );

      if (
        Array.isArray(
          result.payload?.roles
        ) &&
        result.payload.roles.length
      ) {
        setAdminTeamRoles(
          result.payload.roles
        );
      }
    } catch (error) {
      if (!quiet) {
        setMessage(
          error instanceof Error
            ? error.message
            : "Team management could not be loaded."
        );
      }
    } finally {
      setAdminTeamLoading(false);
    }
  }

  function openNewTeamMember() {
    setSelectedAdminTeamMember(null);
    setTeamAdminMode("new");
    setTeamAdminForm(
      blankTeamAdminForm
    );
    setTeamTemporaryPassword("");
    setTeamAdminModalOpen(true);
    setMessage("");
  }

  function openTeamMember(
    person: Profile
  ) {
    setSelectedAdminTeamMember(
      person
    );
    setTeamAdminMode("edit");
    setTeamAdminForm({
      display_name:
        person.display_name || "",
      email:
        person.email || "",
      phone:
        person.phone || "",
      role:
        person.role ||
        "Administrative",
      commission_pct:
        (
          numberOrZero(
            person.default_commission_rate
          ) * 100
        ).toFixed(2).replace(
          /\.00$/,
          ""
        ),
      active:
        person.active !== false,
    });
    setTeamTemporaryPassword("");
    setTeamAdminModalOpen(true);
    setMessage("");
  }

  function closeTeamAdminModal() {
    setTeamAdminModalOpen(false);
    setSelectedAdminTeamMember(null);
    setTeamAdminMode("new");
    setTeamAdminForm(
      blankTeamAdminForm
    );
    setTeamTemporaryPassword("");
  }

  async function saveTeamMember() {
    const name =
      teamAdminForm.display_name.trim();

    const emailValue =
      teamAdminForm.email
        .trim()
        .toLowerCase();

    const commissionPct =
      Number(
        teamAdminForm.commission_pct ||
          0
      );

    if (!name) {
      setMessage(
        "Team member name is required."
      );
      return;
    }

    if (
      teamAdminMode === "new" &&
      (
        !emailValue ||
        !emailValue.includes("@")
      )
    ) {
      setMessage(
        "A valid email is required for a new Hub login."
      );
      return;
    }

    if (
      !Number.isFinite(
        commissionPct
      ) ||
      commissionPct < 0 ||
      commissionPct > 100
    ) {
      setMessage(
        "Commission must be between 0% and 100%."
      );
      return;
    }

    setTeamAdminSaving(true);

    try {
      const result = await teamAdminApi(
        teamAdminMode === "new"
          ? {
              action: "create",
              display_name: name,
              email: emailValue,
              phone:
                teamAdminForm.phone.trim(),
              role:
                teamAdminForm.role,
              default_commission_rate:
                commissionPct / 100,
            }
          : {
              action: "update",
              user_id:
                selectedAdminTeamMember?.id,
              display_name: name,
              phone:
                teamAdminForm.phone.trim(),
              role:
                teamAdminForm.role,
              default_commission_rate:
                commissionPct / 100,
              active:
                teamAdminForm.active,
            }
      );

      if (!result.ok) {
        setMessage(
          result.payload?.error ||
            "Team member could not be saved."
        );
        return;
      }

      if (
        teamAdminMode === "new"
      ) {
        const created =
          result.payload
            ?.user as Profile;

        setSelectedAdminTeamMember(
          created
        );
        setTeamAdminMode("edit");
        setTeamAdminForm({
          display_name:
            created.display_name,
          email:
            created.email || "",
          phone:
            created.phone || "",
          role:
            created.role,
          commission_pct:
            (
              numberOrZero(
                created.default_commission_rate
              ) * 100
            ).toFixed(2).replace(
              /\.00$/,
              ""
            ),
          active:
            created.active !== false,
        });
        setTeamTemporaryPassword(
          result.payload
            ?.temporary_password ||
            ""
        );
      } else {
        const updated =
          result.payload
            ?.user as Profile;

        if (updated?.id) {
          setSelectedAdminTeamMember(
            updated
          );
          setTeamAdminForm(
            (current) => ({
              ...current,
              display_name:
                updated.display_name,
              email:
                updated.email || "",
              phone:
                updated.phone || "",
              role:
                updated.role,
              commission_pct:
                (
                  numberOrZero(
                    updated.default_commission_rate
                  ) * 100
                ).toFixed(2).replace(
                  /\.00$/,
                  ""
                ),
              active:
                updated.active !==
                false,
            })
          );
        }
      }

      await Promise.all([
        loadAdminTeam(true),
        loadTeam(),
        loadProfile(),
      ]);

      setMessage(
        teamAdminMode === "new"
          ? "Team member login created."
          : "Team member updated."
      );
    } catch (error) {
      setMessage(
        error instanceof Error
          ? error.message
          : "Team member could not be saved."
      );
    } finally {
      setTeamAdminSaving(false);
    }
  }

  async function resetTeamPassword() {
    if (
      !selectedAdminTeamMember
    ) {
      return;
    }

    const confirmed =
      window.confirm(
        `Create a new temporary password for ${selectedAdminTeamMember.display_name}?`
      );

    if (!confirmed) return;

    setTeamAdminSaving(true);

    try {
      const result = await teamAdminApi({
        action:
          "reset_password",
        user_id:
          selectedAdminTeamMember.id,
      });

      if (!result.ok) {
        setMessage(
          result.payload?.error ||
            "Password could not be reset."
        );
        return;
      }

      setTeamTemporaryPassword(
        result.payload
          ?.temporary_password ||
          ""
      );

      setMessage(
        "A new temporary password was created."
      );
    } catch (error) {
      setMessage(
        error instanceof Error
          ? error.message
          : "Password could not be reset."
      );
    } finally {
      setTeamAdminSaving(false);
    }
  }

  async function copyTeamPassword() {
    if (
      !teamTemporaryPassword
    ) {
      return;
    }

    try {
      await navigator.clipboard.writeText(
        teamTemporaryPassword
      );
      setMessage(
        "Temporary password copied."
      );
    } catch {
      setMessage(
        "Copy the temporary password manually."
      );
    }
  }

  async function qboApi(
    body: Record<string, unknown>
  ) {
    if (!session?.access_token) {
      throw new Error(
        "Your Hub session is not available."
      );
    }

    const response = await fetch(
      "/api/quickbooks",
      {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${session.access_token}`,
        },
        body: JSON.stringify(body),
      }
    );

    const payload = await response
      .json()
      .catch(() => ({}));

    return {
      ok: response.ok,
      status: response.status,
      payload,
    };
  }

  async function loadQboConnectionStatus(
    quiet = false
  ) {
    if (!session?.access_token) return;

    setQboConnectionLoading(true);

    try {
      const result = await qboApi({
        action: "status",
      });

      if (!result.ok) {
        const message =
          result.payload?.error ||
          "QuickBooks connection setup is not complete yet.";

        setQboConnectionStatus({
          connected: false,
          error: message,
        });

        if (!quiet) setMessage(message);
        return;
      }

      setQboConnectionStatus(
        result.payload as QboConnectionStatus
      );
    } catch (error) {
      const message =
        error instanceof Error
          ? error.message
          : "Could not check QuickBooks connection.";

      setQboConnectionStatus({
        connected: false,
        error: message,
      });

      if (!quiet) setMessage(message);
    } finally {
      setQboConnectionLoading(false);
    }
  }

  function resetQboClientSyncState() {
    setQboClientSyncState({
      status: "idle",
      message: "",
      candidates: [],
    });
  }

  async function syncClientToQuickBooks(
    options?: {
      matchQboCustomerId?: string;
      forceCreate?: boolean;
    }
  ) {
    if (!selectedClient || !supabase) return;

    setQboClientSyncState({
      status: "syncing",
      message: "Syncing client to QuickBooks...",
      candidates: [],
    });

    try {
      const result = await qboApi({
        action: "sync_customer",
        client_id: selectedClient.id,
        ...(options?.matchQboCustomerId
          ? { match_qbo_customer_id: options.matchQboCustomerId }
          : {}),
        ...(options?.forceCreate
          ? { force_create: true }
          : {}),
      });

      if (
        result.status === 409 &&
        result.payload?.status === "match_required"
      ) {
        setQboClientSyncState({
          status: "review",
          message:
            "QuickBooks found possible existing customers. Choose the correct match or create a new customer.",
          candidates: (result.payload?.candidates || []) as QboCustomerCandidate[],
        });
        return;
      }

      if (!result.ok) {
        const message =
          result.payload?.error ||
          "QuickBooks sync failed.";

        setQboClientSyncState({
          status: "error",
          message,
          candidates: [],
        });
        setMessage(message);
        return;
      }

      const { data, error } = await supabase
        .from("clients")
        .select(clientColumns)
        .eq("id", selectedClient.id)
        .single();

      if (!error && data) {
        const refreshed = data as Client;
        setSelectedClient(refreshed);
        setClientForm(clientToForm(refreshed));
      }

      await loadClients();

      setQboClientSyncState({
        status: "success",
        message: result.payload?.operation
          ? `${result.payload.operation} completed successfully.`
          : "Client synced to QuickBooks.",
        candidates: [],
      });

      setMessage(
        `${getClientName(selectedClient)} is synced with QuickBooks.`
      );
    } catch (error) {
      const message =
        error instanceof Error
          ? error.message
          : "QuickBooks sync failed.";

      setQboClientSyncState({
        status: "error",
        message,
        candidates: [],
      });
      setMessage(message);
    }
  }

  function resetQboManufacturerSyncState() {
    setQboManufacturerSyncState({
      status: "idle",
      message: "",
      candidates: [],
    });
  }

  async function syncManufacturerToQuickBooks(
    options?: {
      matchQboVendorId?: string;
      forceCreate?: boolean;
    }
  ) {
    if (
      !selectedManufacturer ||
      !supabase
    ) {
      return;
    }

    setQboManufacturerSyncState({
      status: "syncing",
      message:
        "Syncing manufacturer to QuickBooks...",
      candidates: [],
    });

    try {
      const result = await qboApi({
        action: "sync_vendor",
        manufacturer_id:
          selectedManufacturer.id,
        ...(options?.matchQboVendorId
          ? {
              match_qbo_vendor_id:
                options.matchQboVendorId,
            }
          : {}),
        ...(options?.forceCreate
          ? {
              force_create: true,
            }
          : {}),
      });

      if (
        result.status === 409 &&
        result.payload?.status ===
          "match_required"
      ) {
        setQboManufacturerSyncState({
          status: "review",
          message:
            "QuickBooks found possible existing vendors. Choose the correct match or create a new vendor.",
          candidates:
            (result.payload?.candidates ||
              []) as QboVendorCandidate[],
        });
        return;
      }

      if (!result.ok) {
        const message =
          result.payload?.error ||
          "QuickBooks vendor sync failed.";

        setQboManufacturerSyncState({
          status: "error",
          message,
          candidates: [],
        });

        setMessage(message);
        return;
      }

      const { data, error } =
        await supabase
          .from("manufacturers")
          .select(manufacturerColumns)
          .eq(
            "id",
            selectedManufacturer.id
          )
          .single();

      if (!error && data) {
        const refreshed =
          data as Manufacturer;

        setSelectedManufacturer(
          refreshed
        );
        setManufacturerForm(
          manufacturerToForm(refreshed)
        );
      }

      await loadManufacturers();

      setQboManufacturerSyncState({
        status: "success",
        message:
          result.payload?.operation
            ? `${result.payload.operation} completed successfully.`
            : "Manufacturer synced to QuickBooks.",
        candidates: [],
      });

      setMessage(
        `${selectedManufacturer.name} is synced with QuickBooks.`
      );
    } catch (error) {
      const message =
        error instanceof Error
          ? error.message
          : "QuickBooks vendor sync failed.";

      setQboManufacturerSyncState({
        status: "error",
        message,
        candidates: [],
      });

      setMessage(message);
    }
  }

  async function loadClientDocuments(
    clientId: string
  ) {
    if (!supabase) return;

    setClientDocumentsLoading(true);

    const { data, error } = await supabase
      .from("documents")
      .select(clientDocumentColumns)
      .eq("owner_type", "client")
      .eq("owner_id", clientId)
      .order("uploaded_at", {
        ascending: false,
      });

    if (error) {
      setMessage(
        `Could not load client documents: ${error.message}`
      );
      setClientDocuments([]);
      setClientDocumentsLoading(false);
      return;
    }

    setClientDocuments(
      (data || []) as ClientDocument[]
    );
    setClientDocumentsLoading(false);
  }

  async function uploadClientDocument() {
    if (
      !supabase ||
      !selectedClient ||
      !clientDocumentFile
    ) {
      return;
    }

    if (
      clientDocumentFile.size >
      25 * 1024 * 1024
    ) {
      setMessage(
        "Client documents must be 25 MB or smaller."
      );
      return;
    }

    setUploadingClientDocument(true);
    setMessage("");

    const safeName = clientDocumentFile.name
      .replace(/[^a-zA-Z0-9._-]+/g, "-")
      .replace(/-+/g, "-");

    const storageKey = `${
      selectedClient.id
    }/${Date.now()}-${safeName}`;

    const { error: storageError } =
      await supabase.storage
        .from("client-documents")
        .upload(
          storageKey,
          clientDocumentFile,
          {
            upsert: false,
            contentType:
              clientDocumentFile.type ||
              undefined,
          }
        );

    if (storageError) {
      setMessage(
        `Could not upload document: ${storageError.message}`
      );
      setUploadingClientDocument(false);
      return;
    }

    const { error: recordError } =
      await supabase
        .from("documents")
        .insert({
          owner_type: "client",
          owner_id: selectedClient.id,
          document_type:
            clientDocumentDraft.document_type,
          file_name: clientDocumentFile.name,
          storage_key: storageKey,
          mime_type:
            clientDocumentFile.type || null,
          size_bytes:
            clientDocumentFile.size,
          uploaded_by:
            profile?.id || null,
          metadata: {
            notes:
              clientDocumentDraft.notes.trim() ||
              null,
            expiration_date:
              clientDocumentDraft.expiration_date ||
              null,
          },
        });

    if (recordError) {
      await supabase.storage
        .from("client-documents")
        .remove([storageKey]);

      setMessage(
        `The file uploaded, but its document record could not be saved: ${recordError.message}`
      );
      setUploadingClientDocument(false);
      return;
    }

    setClientDocumentFile(null);
    setClientDocumentDraft(
      blankClientDocumentDraft
    );

    const fileInput =
      document.getElementById(
        "client-document-file"
      ) as HTMLInputElement | null;

    if (fileInput) {
      fileInput.value = "";
    }

    await loadClientDocuments(
      selectedClient.id
    );

    setUploadingClientDocument(false);
    setMessage(
      `${clientDocumentFile.name} was added to ${getClientName(
        selectedClient
      )}.`
    );
  }

  async function viewClientDocument(
    documentRecord: ClientDocument
  ) {
    if (!supabase) return;

    const { data, error } =
      await supabase.storage
        .from("client-documents")
        .createSignedUrl(
          documentRecord.storage_key,
          300
        );

    if (error || !data?.signedUrl) {
      setMessage(
        `Could not open document: ${
          error?.message ||
          "Signed URL unavailable"
        }`
      );
      return;
    }

    window.open(
      data.signedUrl,
      "_blank",
      "noopener,noreferrer"
    );
  }

