  async function saveClientDocumentDetails() {
    if (
      !supabase ||
      !selectedClient ||
      !editingClientDocumentId
    ) {
      return;
    }

    const existing =
      clientDocuments.find(
        (documentRecord) =>
          documentRecord.id ===
          editingClientDocumentId
      );

    if (!existing) return;

    const { error } = await supabase
      .from("documents")
      .update({
        document_type:
          editingClientDocumentDraft.document_type,
        metadata: {
          ...(existing.metadata || {}),
          notes:
            editingClientDocumentDraft.notes.trim() ||
            null,
          expiration_date:
            editingClientDocumentDraft.expiration_date ||
            null,
        },
      })
      .eq(
        "id",
        editingClientDocumentId
      );

    if (error) {
      setMessage(
        `Could not update document details: ${error.message}`
      );
      return;
    }

    setEditingClientDocumentId(null);
    setEditingClientDocumentDraft(
      blankClientDocumentDraft
    );

    await loadClientDocuments(
      selectedClient.id
    );

    setMessage(
      "Client document details were updated."
    );
  }

  async function deleteClientDocument(
    documentRecord: ClientDocument
  ) {
    if (!supabase || !selectedClient) {
      return;
    }

    const confirmed = window.confirm(
      `Delete ${documentRecord.file_name}? This removes the private file and its document record.`
    );

    if (!confirmed) return;

    setDeletingClientDocumentId(
      documentRecord.id
    );
    setMessage("");

    const { error: storageError } =
      await supabase.storage
        .from("client-documents")
        .remove([
          documentRecord.storage_key,
        ]);

    if (storageError) {
      setMessage(
        `Could not delete the stored file: ${storageError.message}`
      );
      setDeletingClientDocumentId(null);
      return;
    }

    const { error: recordError } =
      await supabase
        .from("documents")
        .delete()
        .eq("id", documentRecord.id);

    if (recordError) {
      setMessage(
        `The file was removed, but its document record could not be deleted: ${recordError.message}`
      );
      setDeletingClientDocumentId(null);
      return;
    }

    if (
      editingClientDocumentId ===
      documentRecord.id
    ) {
      setEditingClientDocumentId(null);
      setEditingClientDocumentDraft(
        blankClientDocumentDraft
      );
    }

    await loadClientDocuments(
      selectedClient.id
    );

    setDeletingClientDocumentId(null);
    setMessage(
      `${documentRecord.file_name} was deleted.`
    );
  }

