  async function libraryAiApi(
    body: Record<string, unknown>
  ) {
    if (!session?.access_token) {
      throw new Error(
        "Your Hub session is not available."
      );
    }

    const response = await fetch(
      "/api/library-ai",
      {
        method: "POST",
        headers: {
          "Content-Type":
            "application/json",
          Authorization:
            `Bearer ${session.access_token}`,
        },
        body: JSON.stringify(body),
      }
    );

    const payload = await response
      .json()
      .catch(() => ({}));

    return {
      ok: response.ok,
      status: response.status,
      payload,
    };
  }

  async function runAiFinder() {
    setAiFinderLoading(true);
    setAiFinderHasRun(true);
    setAiFinderInterpretation("");
    setAiFinderModel("");
    setMessage("");

    try {
      const result =
        await libraryAiApi({
          action: "finder",
          prompt:
            aiFinderPrompt.trim(),
          manufacturer_id:
            aiFinderManufacturerId ||
            null,
          category:
            aiFinderCategory.trim() ||
            null,
          collection:
            aiFinderCollection.trim() ||
            null,
          max_msrp:
            aiFinderMaxMsrp.trim() ===
            ""
              ? null
              : numberOrZero(
                  aiFinderMaxMsrp
                ),
          priced_only:
            aiFinderPricedOnly,
        });

      if (!result.ok) {
        const errorMessage =
          result.payload?.error ||
          "AI Finder could not complete the search.";

        setAiFinderResults([]);

        if (
          result.payload
            ?.setup_required ===
          "OPENAI_API_KEY"
        ) {
          window.alert(
            "The real AI Finder is built and ready, but the OpenAI API key still needs to be added to Vercel during setup."
          );
        } else {
          window.alert(
            errorMessage
          );
        }

        return;
      }

      setAiFinderResults(
        (result.payload
          ?.results ||
          []) as AiFinderResult[]
      );

      setAiFinderInterpretation(
        result.payload
          ?.interpretation ||
          ""
      );

      setAiFinderModel(
        result.payload?.model ||
          ""
      );

      if (
        !result.payload?.results
          ?.length
      ) {
        setMessage(
          "No catalog products matched those Finder filters."
        );
      }
    } catch (error) {
      setAiFinderResults([]);
      window.alert(
        error instanceof Error
          ? error.message
          : "AI Finder could not complete the search."
      );
    } finally {
      setAiFinderLoading(false);
    }
  }

  function clearAiFinder() {
    setAiFinderPrompt("");
    setAiFinderManufacturerId("");
    setAiFinderCategory("");
    setAiFinderCollection("");
    setAiFinderMaxMsrp("");
    setAiFinderPricedOnly(false);
    setAiFinderResults([]);
    setAiFinderHasRun(false);
    setAiFinderInterpretation("");
    setAiFinderModel("");
    setMessage("");
  }

  function aiFinderDefaultClientPrice(
    manufacturer: Manufacturer | null,
    msrp: number
  ) {
    const discount = numberOrZero(
      manufacturer?.default_discount_pct
    );

    return (
      numberOrZero(msrp) *
      (1 - discount / 100)
    );
  }

  function aiFinderExpectedUnitCost(
    manufacturer: Manufacturer | null,
    msrp: number
  ) {
    const factor = numberOrZero(
      manufacturer?.purchasing_factor
    );
    const tariff = numberOrZero(
      manufacturer?.tariff_pct
    );
    const surcharge = numberOrZero(
      manufacturer?.surcharge_pct
    );

    if (!factor) return null;

    return (
      numberOrZero(msrp) *
      factor *
      (1 + tariff / 100 + surcharge / 100)
    );
  }

