  async function saveCatalog() {
    if (!supabase) return;

    if (!catalogForm.manufacturer_id) {
      window.alert("Choose a manufacturer.");
      return;
    }

    if (!catalogForm.title.trim()) {
      window.alert("Catalog title is required.");
      return;
    }

    setSavingCatalog(true);

    const year =
      catalogForm.catalog_year.trim() === ""
        ? null
        : Math.trunc(
            numberOrZero(catalogForm.catalog_year)
          );

    const payload = {
      manufacturer_id: catalogForm.manufacturer_id,
      title: catalogForm.title.trim(),
      catalog_year: year,
      source_url:
        catalogForm.source_url.trim() || null,
      notes: catalogForm.notes.trim() || null,
      active: catalogForm.active,
      updated_at: new Date().toISOString(),
    };

    let saved: Catalog | null = null;

    if (catalogMode === "new") {
      const { data, error } = await supabase
        .from("catalogs")
        .insert({
          ...payload,
          created_by: profile?.id || null,
        })
        .select(catalogColumns)
        .single();

      if (error || !data) {
        setSavingCatalog(false);
        window.alert(
          `Could not create catalog: ${
            error?.message || "Unknown error"
          }`
        );
        return;
      }

      saved = data as Catalog;
    } else if (selectedCatalog) {
      const { data, error } = await supabase
        .from("catalogs")
        .update(payload)
        .eq("id", selectedCatalog.id)
        .select(catalogColumns)
        .single();

      if (error || !data) {
        setSavingCatalog(false);
        window.alert(
          `Could not save catalog: ${
            error?.message || "Unknown error"
          }`
        );
        return;
      }

      saved = data as Catalog;
    }

    if (!saved) {
      setSavingCatalog(false);
      return;
    }

    await supabase
      .from("catalog_items")
      .update({
        manufacturer_id: saved.manufacturer_id,
        updated_at: new Date().toISOString(),
      })
      .eq("catalog_id", saved.id);

    setSelectedCatalog(saved);
    setCatalogForm(catalogToForm(saved));
    setCatalogMode("view");
    await Promise.all([
      loadCatalogs(),
      loadCatalogItems(saved.id),
    ]);
    setSavingCatalog(false);
    setMessage(`${saved.title} saved.`);
  }

  async function deleteCatalog() {
    if (!supabase || !selectedCatalog) return;

    const confirmed = window.confirm(
      `Delete ${selectedCatalog.title}? Its structured catalog items will also be deleted.`
    );

    if (!confirmed) return;

    if (selectedCatalog.file_path) {
      const { error: storageError } =
        await supabase.storage
          .from("catalogs")
          .remove([selectedCatalog.file_path]);

      if (storageError) {
        window.alert(
          `Could not remove catalog PDF: ${storageError.message}`
        );
        return;
      }
    }

    const { error } = await supabase
      .from("catalogs")
      .delete()
      .eq("id", selectedCatalog.id);

    if (error) {
      window.alert(
        `Could not delete catalog: ${error.message}`
      );
      return;
    }

    closeCatalogModal();
    await loadCatalogs();
    setMessage("Catalog deleted.");
  }

  async function uploadCatalogPdf(file: File) {
    if (!supabase || !selectedCatalog) return;

    const isPdf =
      file.type === "application/pdf" ||
      file.name.toLowerCase().endsWith(".pdf");

    if (!isPdf) {
      window.alert("Please choose a PDF catalog.");
      return;
    }

    const maxBytes = 50 * 1024 * 1024;
    if (file.size > maxBytes) {
      window.alert(
        "That PDF is larger than 50 MB. Please use a smaller file."
      );
      return;
    }

    setUploadingCatalogPdf(true);

    const safeName = file.name
      .replace(/[^a-zA-Z0-9._-]+/g, "-")
      .replace(/-+/g, "-");

    const storagePath =
      `${selectedCatalog.id}/` +
      `${Date.now()}-${safeName}`;

    const { error: uploadError } = await supabase.storage
      .from("catalogs")
      .upload(storagePath, file, {
        cacheControl: "3600",
        upsert: false,
        contentType: "application/pdf",
      });

    if (uploadError) {
      setUploadingCatalogPdf(false);
      window.alert(
        `Could not upload catalog PDF: ${uploadError.message}`
      );
      return;
    }

    const previousPath = selectedCatalog.file_path;

    const { data, error: updateError } = await supabase
      .from("catalogs")
      .update({
        file_name: file.name,
        file_path: storagePath,
        updated_at: new Date().toISOString(),
      })
      .eq("id", selectedCatalog.id)
      .select(catalogColumns)
      .single();

    if (updateError || !data) {
      await supabase.storage
        .from("catalogs")
        .remove([storagePath]);

      setUploadingCatalogPdf(false);
      window.alert(
        `The PDF uploaded, but the catalog record could not be updated: ${
          updateError?.message || "Unknown error"
        }`
      );
      return;
    }

    if (
      previousPath &&
      previousPath !== storagePath
    ) {
      await supabase.storage
        .from("catalogs")
        .remove([previousPath]);
    }

    const updated = data as Catalog;
    setSelectedCatalog(updated);
    setCatalogForm(catalogToForm(updated));
    await loadCatalogs();
    setUploadingCatalogPdf(false);
    setMessage(`${updated.title} PDF uploaded.`);
  }

  async function viewLibraryPdf(
    bucket: "catalogs" | "price-lists",
    filePath: string | null
  ) {
    if (!supabase || !filePath) return;

    const { data, error } = await supabase.storage
      .from(bucket)
      .createSignedUrl(filePath, 600);

    if (error || !data?.signedUrl) {
      window.alert(
        `Could not open PDF: ${
          error?.message || "No signed URL was returned."
        }`
      );
      return;
    }

    window.open(
      data.signedUrl,
      "_blank",
      "noopener,noreferrer"
    );
  }

