  async function aiImportCatalogPdf() {
    if (
      !selectedCatalog ||
      !selectedCatalog.file_path
    ) {
      window.alert(
        "Upload the catalog PDF first."
      );
      return;
    }

    const confirmed =
      window.confirm(
        `AI will read ${selectedCatalog.file_name || "this catalog PDF"} and replace this catalog's current structured product rows. Continue?`
      );

    if (!confirmed) return;

    setCatalogAiImporting(true);
    setMessage("");

    try {
      const result =
        await libraryAiApi({
          action:
            "ingest_catalog",
          catalog_id:
            selectedCatalog.id,
        });

      if (!result.ok) {
        const errorMessage =
          result.payload?.error ||
          "AI catalog import failed.";

        if (
          result.payload
            ?.setup_required ===
          "OPENAI_API_KEY"
        ) {
          window.alert(
            "AI catalog importing is built and ready, but the OpenAI API key still needs to be added to Vercel during setup."
          );
        } else {
          window.alert(
            errorMessage
          );
        }

        return;
      }

      await Promise.all([
        loadCatalogItems(
          selectedCatalog.id
        ),
        loadCatalogs(),
      ]);

      const count =
        Number(
          result.payload
            ?.imported_count || 0
        );

      const confidence =
        Number(
          result.payload
            ?.overall_confidence
        );

      setMessage(
        `AI imported ${count} catalog ${
          count === 1
            ? "product"
            : "products"
        }${
          Number.isFinite(
            confidence
          )
            ? ` at ${Math.round(
                confidence * 100
              )}% document confidence`
            : ""
        }.`
      );
    } catch (error) {
      window.alert(
        error instanceof Error
          ? error.message
          : "AI catalog import failed."
      );
    } finally {
      setCatalogAiImporting(false);
    }
  }

