  async function savePriceList() {
    if (!supabase) return;

    if (!priceListForm.manufacturer_id) {
      window.alert("Choose a manufacturer.");
      return;
    }

    if (!priceListForm.title.trim()) {
      window.alert("Price list title is required.");
      return;
    }

    if (
      priceListForm.approved_for_pricing &&
      !priceListForm.active
    ) {
      window.alert(
        "A price list must be Active before it can be Approved for Pricing."
      );
      return;
    }

    setSavingPriceList(true);

    // Keep pricing authority simple: approving one list
    // unapproves the other lists for the same manufacturer.
    if (priceListForm.approved_for_pricing) {
      let unapproveQuery = supabase
        .from("price_lists")
        .update({
          approved_for_pricing: false,
          updated_at: new Date().toISOString(),
        })
        .eq(
          "manufacturer_id",
          priceListForm.manufacturer_id
        );

      if (selectedPriceList) {
        unapproveQuery = unapproveQuery.neq(
          "id",
          selectedPriceList.id
        );
      }

      const { error: unapproveError } =
        await unapproveQuery;

      if (unapproveError) {
        setSavingPriceList(false);
        window.alert(
          `Could not update pricing approval: ${unapproveError.message}`
        );
        return;
      }
    }

    const payload = {
      manufacturer_id:
        priceListForm.manufacturer_id,
      title: priceListForm.title.trim(),
      version:
        priceListForm.version.trim() || null,
      effective_date:
        priceListForm.effective_date || null,
      expiration_date:
        priceListForm.expiration_date || null,
      source_url:
        priceListForm.source_url.trim() || null,
      approved_for_pricing:
        priceListForm.approved_for_pricing,
      active: priceListForm.active,
      notes:
        priceListForm.notes.trim() || null,
      updated_at: new Date().toISOString(),
    };

    let saved: PriceList | null = null;

    if (priceListMode === "new") {
      const { data, error } = await supabase
        .from("price_lists")
        .insert({
          ...payload,
          created_by: profile?.id || null,
        })
        .select(priceListColumns)
        .single();

      if (error || !data) {
        setSavingPriceList(false);
        window.alert(
          `Could not create price list: ${
            error?.message || "Unknown error"
          }`
        );
        return;
      }

      saved = data as PriceList;
    } else if (selectedPriceList) {
      const { data, error } = await supabase
        .from("price_lists")
        .update(payload)
        .eq("id", selectedPriceList.id)
        .select(priceListColumns)
        .single();

      if (error || !data) {
        setSavingPriceList(false);
        window.alert(
          `Could not save price list: ${
            error?.message || "Unknown error"
          }`
        );
        return;
      }

      saved = data as PriceList;
    }

    if (!saved) {
      setSavingPriceList(false);
      return;
    }

    await supabase
      .from("price_list_items")
      .update({
        manufacturer_id: saved.manufacturer_id,
        updated_at: new Date().toISOString(),
      })
      .eq("price_list_id", saved.id);

    setSelectedPriceList(saved);
    setPriceListForm(priceListToForm(saved));
    setPriceListMode("view");

    await Promise.all([
      loadPriceLists(),
      loadPriceListItems(saved.id),
    ]);

    setSavingPriceList(false);
    setMessage(`${saved.title} saved.`);
  }

