  async function uploadPriceListPdf(file: File) {
    if (!supabase || !selectedPriceList) return;

    const isPdf =
      file.type === "application/pdf" ||
      file.name.toLowerCase().endsWith(".pdf");

    if (!isPdf) {
      window.alert("Please choose a PDF price list.");
      return;
    }

    const maxBytes = 50 * 1024 * 1024;
    if (file.size > maxBytes) {
      window.alert(
        "That PDF is larger than 50 MB. Please use a smaller file."
      );
      return;
    }

    setUploadingPriceListPdf(true);

    const safeName = file.name
      .replace(/[^a-zA-Z0-9._-]+/g, "-")
      .replace(/-+/g, "-");

    const storagePath =
      `${selectedPriceList.id}/` +
      `${Date.now()}-${safeName}`;

    const { error: uploadError } = await supabase.storage
      .from("price-lists")
      .upload(storagePath, file, {
        cacheControl: "3600",
        upsert: false,
        contentType: "application/pdf",
      });

    if (uploadError) {
      setUploadingPriceListPdf(false);
      window.alert(
        `Could not upload price-list PDF: ${uploadError.message}`
      );
      return;
    }

    const previousPath = selectedPriceList.file_path;

    const { data, error: updateError } = await supabase
      .from("price_lists")
      .update({
        file_name: file.name,
        file_path: storagePath,
        updated_at: new Date().toISOString(),
      })
      .eq("id", selectedPriceList.id)
      .select(priceListColumns)
      .single();

    if (updateError || !data) {
      await supabase.storage
        .from("price-lists")
        .remove([storagePath]);

      setUploadingPriceListPdf(false);
      window.alert(
        `The PDF uploaded, but the price-list record could not be updated: ${
          updateError?.message || "Unknown error"
        }`
      );
      return;
    }

    if (
      previousPath &&
      previousPath !== storagePath
    ) {
      await supabase.storage
        .from("price-lists")
        .remove([previousPath]);
    }

    const updated = data as PriceList;
    setSelectedPriceList(updated);
    setPriceListForm(priceListToForm(updated));
    await loadPriceLists();
    setUploadingPriceListPdf(false);
    setMessage(`${updated.title} PDF uploaded.`);
  }

