  async function aiImportPriceListPdf() {
    if (
      !selectedPriceList ||
      !selectedPriceList.file_path
    ) {
      window.alert(
        "Upload the price-list PDF first."
      );
      return;
    }

    const approvedMessage =
      selectedPriceList
        .approved_for_pricing
        ? " This document is currently Approved for Pricing, but AI import will not change that approval status."
        : " AI import will NOT approve this document for pricing.";

    const confirmed =
      window.confirm(
        `AI will read ${selectedPriceList.file_name || "this price-list PDF"} and replace this price list's current structured SKU/MSRP rows.${approvedMessage} Continue?`
      );

    if (!confirmed) return;

    setPriceListAiImporting(true);
    setMessage("");

    try {
      const result =
        await libraryAiApi({
          action:
            "ingest_price_list",
          price_list_id:
            selectedPriceList.id,
        });

      if (!result.ok) {
        const errorMessage =
          result.payload?.error ||
          "AI price-list import failed.";

        if (
          result.payload
            ?.setup_required ===
          "OPENAI_API_KEY"
        ) {
          window.alert(
            "AI price-list importing is built and ready, but the OpenAI API key still needs to be added to Vercel during setup."
          );
        } else {
          window.alert(
            errorMessage
          );
        }

        return;
      }

      await Promise.all([
        loadPriceListItems(
          selectedPriceList.id
        ),
        loadPriceLists(),
      ]);

      const count =
        Number(
          result.payload
            ?.imported_count || 0
        );

      const confidence =
        Number(
          result.payload
            ?.overall_confidence
        );

      setMessage(
        `AI imported ${count} ${
          count === 1
            ? "price row"
            : "price rows"
        }${
          Number.isFinite(
            confidence
          )
            ? ` at ${Math.round(
                confidence * 100
              )}% document confidence`
            : ""
        }. Pricing approval was not changed.`
      );
    } catch (error) {
      window.alert(
        error instanceof Error
          ? error.message
          : "AI price-list import failed."
      );
    } finally {
      setPriceListAiImporting(false);
    }
  }

