  async function pushVendorInvoiceToQuickBooks() {
    if (
      !selectedVendorInvoice ||
      !supabase
    ) {
      return;
    }

    const invoice =
      selectedVendorInvoice;

    setQboVendorInvoicePushingId(
      invoice.id
    );
    setQboAccountingMessage(
      `invoice:${invoice.id}`,
      "Pushing Vendor Invoice to QuickBooks..."
    );

    try {
      const result = await qboApi({
        action: "sync_bill",
        vendor_invoice_id:
          invoice.id,
      });

      if (!result.ok) {
        const message =
          result.payload?.error ||
          "QuickBooks Bill push failed.";

        setQboAccountingMessage(
          `invoice:${invoice.id}`,
          message
        );

        if (
          result.status !== 409
        ) {
          setMessage(message);
        }
        return;
      }

      const { data, error } =
        await supabase
          .from("vendor_invoices")
          .select(
            vendorInvoiceColumns
          )
          .eq("id", invoice.id)
          .single();

      if (!error && data) {
        setSelectedVendorInvoice(
          data as VendorInvoice
        );
      }

      await loadAccounting();

      setQboAccountingMessage(
        `invoice:${invoice.id}`,
        "Pushed to QuickBooks as a Bill."
      );
      setMessage(
        `Vendor Invoice #${invoice.invoice_number} was pushed to QuickBooks.`
      );
    } catch (error) {
      const message =
        error instanceof Error
          ? error.message
          : "QuickBooks Bill push failed.";

      setQboAccountingMessage(
        `invoice:${invoice.id}`,
        message
      );
      setMessage(message);
    } finally {
      setQboVendorInvoicePushingId(
        ""
      );
    }
  }

